from typing import Optional, Sequence, Union
import unittest

Number = Union[int, float]


def trailing_mean(sales: Sequence[Number], day: int, window: int = 7) -> Optional[float]:
    """Forecast sales for `day` as the mean of up to `window` prior days.

    Averages sales[day - window : day] (never including sales[day] itself).
    If fewer than `window` prior days exist, averages those available.
    Returns None when there is no history (day == 0 or sales is empty).

    Raises ValueError if window < 1, day < 0, or day > len(sales).
    """
    if window < 1:
        raise ValueError("window must be at least 1")
    if day < 0:
        raise ValueError("day must be non-negative")
    if day > len(sales):
        raise ValueError("day must not exceed len(sales)")

    start = max(0, day - window)  # clamp so a negative start does not wrap around
    history = sales[start:day]
    if not history:
        return None
    return float(sum(history) / len(history))


class TrailingMeanTests(unittest.TestCase):
    def setUp(self) -> None:
        self.sales = [10, 20, 30, 40, 50, 60, 70, 80]

    def test_no_history_returns_none(self) -> None:
        self.assertIsNone(trailing_mean(self.sales, 0))

    def test_empty_sales_returns_none(self) -> None:
        self.assertIsNone(trailing_mean([], 0))

    def test_single_prior_day(self) -> None:
        self.assertEqual(trailing_mean(self.sales, 1), 10.0)

    def test_partial_window(self) -> None:
        self.assertEqual(trailing_mean(self.sales, 3), 20.0)

    def test_full_window(self) -> None:
        self.assertEqual(trailing_mean(self.sales, 7), 40.0)

    def test_forecast_next_day(self) -> None:
        self.assertEqual(trailing_mean(self.sales, 8), 50.0)

    def test_custom_window(self) -> None:
        self.assertEqual(trailing_mean(self.sales, 5, window=2), 45.0)

    def test_excludes_current_day(self) -> None:
        # A huge value on the forecast day must not affect the result.
        self.assertEqual(trailing_mean([10, 20, 1000], 2), 15.0)

    def test_negative_start_is_clamped(self) -> None:
        # day - window = -5; must not wrap around as a negative slice index.
        self.assertEqual(trailing_mean(self.sales, 2, window=7), 15.0)

